const QUIZ_DATA = {"2024": [{"q": "Which of the following statements are correct regarding the National Judicial Appointments Commission (NJAC)? It consists of: (a) CJI as ex-officio Chairperson (b) Two other senior judges of SC as ex-officio members (c) Union Law Minister as ex-officio member (d) Two eminent persons nominated by the committee", "options": {"A": "(a) and (c)", "B": "(b) and (d)", "C": "(a) and (d)", "D": "All of the above"}, "correct": "D", "explanation": "NJAC (99th Amendment, 2014) was to consist of the CJI as chairperson, two senior-most SC judges, the Union Law Minister, and two eminent persons nominated by a committee of PM, CJI and Leader of Opposition — all statements are correct.", "subject": "Polity", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Which of the following was a tax levied on pastures (grazing lands) in ancient India?", "options": {"A": "Akshayanivi", "B": "Bhaga", "C": "Bhagna-Pravistaka", "D": "Viveet"}, "correct": "D", "explanation": "'Vivita' (विवीत) was the tax levied on pasture/grazing lands in ancient India's revenue system.", "subject": "History", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "On the basis of Chelliah Committee's recommendations, in which of the following fields were reforms initiated?", "options": {"A": "Monetary Policy", "B": "Trade Policy", "C": "Foreign Exchange Policy", "D": "Tax Policy"}, "correct": "D", "explanation": "The Chelliah Committee (1991) was constituted to recommend reforms in India's tax structure — direct and indirect taxes.", "subject": "Economy", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Which of the following Bangla newspaper underwent a rapid transformation, changing overnight into an English newspaper in order to circumvent the Vernacular Press Act of 1878?", "options": {"A": "Yugantar Patrika", "B": "Anand Bazar Patrika", "C": "Samachar Darpan", "D": "Amrita Bazar Patrika"}, "correct": "D", "explanation": "Amrita Bazar Patrika switched from Bengali to English overnight to escape the restrictions of the Vernacular Press Act, 1878, which applied only to vernacular-language papers.", "subject": "History", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Ahar or Banas culture was a contemporary of which culture?", "options": {"A": "Harappa culture", "B": "Mughal period culture", "C": "Mauryan period culture", "D": "Gupta period culture"}, "correct": "A", "explanation": "The Ahar-Banas culture of Rajasthan (Chalcolithic, c. 2600-1900 BCE) was contemporaneous with the Harappan (Indus Valley) civilisation.", "subject": "History", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Who was the first Deputy Prime Minister of India?", "options": {"A": "Sri Morarji Desai", "B": "Sri Jagjivan Ram", "C": "Chaudhary Charan Singh", "D": "Sardar Vallabhbhai Patel"}, "correct": "D", "explanation": "Sardar Vallabhbhai Patel served as India's first Deputy Prime Minister (and first Home Minister) from 1947 to 1950.", "subject": "Polity/History", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Who among the following is not a member of the high level committee constituted on simultaneous elections?", "options": {"A": "Dr. Niten Chandra", "B": "Dr. Subhash C. Kashyap", "C": "Sri Tushar Mehta", "D": "Sri N.K. Singh"}, "correct": "C", "explanation": "The High-Level Committee on Simultaneous Elections (chaired by Ram Nath Kovind) includes Amit Shah, Ghulam Nabi Azad, N.K. Singh, Subhash C. Kashyap, Harish Salve and Sanjay Kothari — Solicitor General Tushar Mehta is not a member.", "subject": "Polity/Current Affairs", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Who is the founder of the \"Indian Statistical Institute\"?", "options": {"A": "V.K.R.V. Rao", "B": "Prof. Raj Krishna", "C": "P.C. Mahalanobis", "D": "D.T. Lakdawala"}, "correct": "C", "explanation": "Prasanta Chandra Mahalanobis founded the Indian Statistical Institute (ISI) in 1931.", "subject": "Economy/GK", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Which of the following Himalayan peaks is not situated in India?", "options": {"A": "Kamet", "B": "Dhaulagiri", "C": "Namcha Barwa", "D": "Nanga Parbat"}, "correct": "B", "explanation": "Dhaulagiri is located in Nepal; Kamet, Namcha Barwa and Nanga Parbat lie within/near India.", "subject": "Geography", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Which of the following memory of the computer is used to speed up computer processing?", "options": {"A": "Cache memory", "B": "RAM", "C": "ROM", "D": "None of the above"}, "correct": "A", "explanation": "Cache memory sits close to the processor and provides high-speed access to frequently used data, speeding up processing.", "subject": "Computer Science", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Whose composition is \"Natyashastra\"?", "options": {"A": "Vishwanath", "B": "Bhamah", "C": "Bharatamuni", "D": "Bhavbhuti"}, "correct": "C", "explanation": "The Natyashastra, the foundational treatise on performing arts, was composed by Bharatamuni.", "subject": "Art & Culture", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "As per the Economic Survey 2022-23, which of the following commodities had the highest percent share in India's exports in FY 2021-22?", "options": {"A": "Agriculture and allied products", "B": "Crude oil and petroleum products", "C": "Manufactured goods", "D": "Ore and minerals"}, "correct": "C", "explanation": "Per the Economic Survey 2022-23, manufactured goods (engineering goods, chemicals, textiles, electronics) had the highest share in India's exports in FY 2021-22.", "subject": "Economy", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Maximum diversity of species is found at", "options": {"A": "Temperate region", "B": "Tropical region", "C": "Polar region", "D": "None of the above"}, "correct": "B", "explanation": "Tropical regions have warm, humid climates that support the highest species diversity (e.g., rainforests).", "subject": "Biology/Environment", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "What are Residuary subjects?", "options": {"A": "Subjects included in the State list", "B": "Subjects included in the Concurrent list", "C": "Subjects not included in any list", "D": "Subjects included in the Union list"}, "correct": "C", "explanation": "Residuary subjects are those not covered in the Union, State, or Concurrent Lists; Parliament alone can legislate on them (Article 248).", "subject": "Polity", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "'Kanika Siwach' is related to which game?", "options": {"A": "Weightlifting", "B": "Long Jump", "C": "Hockey", "D": "Archery"}, "correct": "C", "explanation": "Kanika Siwach is a member of the Indian junior women's hockey team; she scored key goals in the Women's Junior Asia Cup 2024.", "subject": "Sports", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Which one of the following Gupta ruler is referred to as \"Lichchhavi Dauhitra\" (son of the daughter of the Lichchhavis)?", "options": {"A": "Chandragupta - I", "B": "Samudragupta", "C": "Chandragupta - II", "D": "Skandagupta"}, "correct": "B", "explanation": "Samudragupta is referred to as 'Lichchhavi Dauhitra' since his father Chandragupta I married the Lichchhavi princess Kumaradevi.", "subject": "History", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "As per Union Budget 2024-25 of India, estimated Fiscal Deficit for the Financial year 2024-25 as percentage of Gross Domestic Product is", "options": {"A": "4.9 percent", "B": "3.9 percent", "C": "2.9 percent", "D": "3.5 percent"}, "correct": "A", "explanation": "The Union Budget 2024-25 estimated the fiscal deficit at 4.9% of GDP for FY 2024-25.", "subject": "Economy", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "A group of individual organism with fundamental similarities is called as a", "options": {"A": "Family", "B": "Species", "C": "Genus", "D": "Order"}, "correct": "B", "explanation": "A group of organisms with fundamental similarities capable of interbreeding is called a Species — the basic unit of biological classification.", "subject": "Biology", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "The Ministry of Tribal Affairs in India was established in the year", "options": {"A": "1991", "B": "1995", "C": "1999", "D": "2001"}, "correct": "C", "explanation": "The Ministry of Tribal Affairs was carved out and established in 1999.", "subject": "Polity/GK", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Who has said that 'Conscious body is the soul'?", "options": {"A": "Nagarjuna", "B": "Charvak", "C": "Mimamsa", "D": "Asang"}, "correct": "B", "explanation": "The Charvaka (Lokayata) school of philosophy held the materialist view that the conscious body itself is the soul, rejecting concepts like rebirth.", "subject": "Philosophy", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Which of the following is not a green house gas?", "options": {"A": "Methane", "B": "Chlorofluorocarbon", "C": "Carbon dioxide", "D": "Nitrogen"}, "correct": "D", "explanation": "Nitrogen (N2), though ~78% of the atmosphere, does not act as a greenhouse gas; methane, CFCs and CO2 do.", "subject": "Environment", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Under which Article of the Indian Constitution, the Governor reserves a Bill passed by the State Legislature for President's consideration?", "options": {"A": "Article 199", "B": "Article 200", "C": "Article 201", "D": "Article 356"}, "correct": "B", "explanation": "Article 200 empowers the Governor to reserve a state Bill for the President's consideration.", "subject": "Polity", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Who among the following was conferred with the title of 'Jagat guru' by Akbar?", "options": {"A": "Jinchandra Suri", "B": "Hir Vijay Suri", "C": "Shanti Chandra", "D": "Birbal"}, "correct": "B", "explanation": "Akbar conferred the title 'Jagat Guru' upon the Jain monk Hir Vijay Suri.", "subject": "History", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "In the Nyaya Philosophy, the synonym of Knowledge is", "options": {"A": "Cognition", "B": "Apprehension", "C": "Both (A) and (B)", "D": "None of the above"}, "correct": "C", "explanation": "In Nyaya philosophy, both 'Buddhi' (Cognition) and 'Upalabdhi' (Apprehension) are used as synonyms for knowledge.", "subject": "Philosophy", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Which of the following Article is called the \"Heart and Soul\" of the Indian Constitution?", "options": {"A": "Article 32", "B": "Article 14", "C": "Article 15", "D": "Article 19"}, "correct": "A", "explanation": "Dr. B.R. Ambedkar described Article 32 (Right to Constitutional Remedies) as the 'Heart and Soul' of the Constitution.", "subject": "Polity", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Match List-I (Scheduled Tribe) with List-II (Dominating region): (a) Jarawa (b) Munda (c) Bhil (d) Gaddi -- (1) Rajasthan (2) Himachal Pradesh (3) Andaman & Nicobar Islands (4) Jharkhand", "options": {"A": "(1)(2)(3)(4)", "B": "(2)(1)(4)(3)", "C": "(4)(3)(1)(2)", "D": "(3)(4)(1)(2)"}, "correct": "D", "explanation": "Jarawa-Andaman & Nicobar(3), Munda-Jharkhand(4), Bhil-Rajasthan(1), Gaddi-Himachal Pradesh(2).", "subject": "Geography/Tribes", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "As per the census of India 2011, the Union Territory having lowest sex ratio in the country is", "options": {"A": "Dadra and Nagar Haveli", "B": "Andaman and Nicobar Islands", "C": "Daman and Diu", "D": "Chandigarh"}, "correct": "C", "explanation": "As per Census 2011, Daman and Diu had the lowest sex ratio (618 females per 1000 males) among UTs.", "subject": "Geography", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "What is the scientific name of Leopard?", "options": {"A": "Panthera leo", "B": "Panthera pardus", "C": "Panthera tigris", "D": "Panthera uncia"}, "correct": "B", "explanation": "The scientific name of the Leopard is Panthera pardus (Panthera leo is lion, tigris is tiger, uncia is snow leopard).", "subject": "Biology", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "In India classification of cities on the basis of size of population are in how many categories?", "options": {"A": "03", "B": "04", "C": "05", "D": "06"}, "correct": "D", "explanation": "Census of India classifies towns into 6 classes (Class I to VI) based on population size.", "subject": "Geography", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "The two great leaders of the revolution of 1857, who escaped to Nepal?", "options": {"A": "Nana Saheb and Begum Zeenat Mahal", "B": "Kunwar Singh and Nana Saheb", "C": "Prince Firoz Shah and Begum Hazrat Mahal", "D": "Nana Saheb and Begum Hazrat Mahal"}, "correct": "D", "explanation": "Both Nana Saheb and Begum Hazrat Mahal fled to Nepal to escape British forces after the revolt of 1857.", "subject": "History", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "According to Buddhist Philosophy, the cause of Sanskar (impressions) is", "options": {"A": "Vigyan (Consciousness)", "B": "Vedana (Sense-Experience)", "C": "Avidya (Ignorance)", "D": "None of the above"}, "correct": "C", "explanation": "In the Buddhist doctrine of Pratityasamutpada (Dependent Origination), Avidya (ignorance) is the cause of Sanskar (karmic formations).", "subject": "Philosophy", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "With reference to Asia-Pacific Deaf Games 2024 held at Kuala Lumpur, consider the following statements: (a) It was 11th Asia-Pacific Deaf Games (b) India received 5th rank (c) Indian team bagged 8 Gold, 18 Silver and 29 Bronze medal (d) India did not participate", "options": {"A": "only (a) and (b)", "B": "only (b) and (c)", "C": "only (a) and (c)", "D": "only (d)"}, "correct": "B", "explanation": "It was actually the 10th Asia-Pacific Deaf Games (not 11th) — India did participate and finished 5th with 8 Gold, 18 Silver, 29 Bronze medals; so only (b) and (c) are correct.", "subject": "Sports/Current Affairs", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "The Eastern and the Western Ghats meet each other at", "options": {"A": "Kaimur ranges", "B": "Vindhyan ranges", "C": "Nilgiri hills", "D": "Rajmahal hills"}, "correct": "C", "explanation": "The Eastern and Western Ghats converge at the Nilgiri Hills.", "subject": "Geography", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "The dimension of dielectric constant is", "options": {"A": "M0L0T0", "B": "ML0T0", "C": "MLT0", "D": "M0L0T"}, "correct": "A", "explanation": "Dielectric constant is a dimensionless ratio (permittivity of medium/permittivity of vacuum), so its dimension is M0L0T0.", "subject": "Physics", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "'PM-AASHA' Scheme is related to the welfare of", "options": {"A": "Women", "B": "Disabled", "C": "Farmer", "D": "Student"}, "correct": "C", "explanation": "PM-AASHA (Pradhan Mantri Annadata Aay SanraksHan Abhiyan) is aimed at ensuring remunerative prices to farmers for their produce.", "subject": "Economy", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Who among the following traveller visited the court of Vijaynagar ruler Devray II as a Persian Ambassador?", "options": {"A": "Barbosa", "B": "Nicolo-de-Conti", "C": "Afanasy Nikitin", "D": "Abdur Razzaq"}, "correct": "D", "explanation": "Abdur Razzaq, sent by the Timurid ruler Shah Rukh, visited Devaraya II's court as the Persian ambassador in 1442 CE.", "subject": "History", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "By which of the following names is \"Gandhara\" style known?", "options": {"A": "Indo Persian Art", "B": "Indo Greek Art", "C": "Indo Chinese Art", "D": "Indo European Art"}, "correct": "B", "explanation": "The Gandhara school of art is also known as Indo-Greek art, blending Indian subject matter with Greco-Roman artistic style.", "subject": "Art & Culture", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Green Plants in Ecosystem are", "options": {"A": "Primary Producer", "B": "Primary Consumer", "C": "Secondary Consumer", "D": "Decomposer"}, "correct": "A", "explanation": "Green plants, through photosynthesis, are the primary producers in an ecosystem, forming the base of the food chain.", "subject": "Biology/Environment", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "A Minister who for any period of six (6) consecutive months is not a member of either House of Parliament shall cease to be a Minister after the expiry of this period. This is mentioned in which Article of the Constitution?", "options": {"A": "Article 75(5)", "B": "Article 75(3)", "C": "Article 75(4)", "D": "Article 75(2)"}, "correct": "A", "explanation": "Article 75(5) of the Constitution provides that a Minister who is not an MP for six consecutive months ceases to be a Minister.", "subject": "Polity", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Why \"MITTI\" cafe are famous?", "options": {"A": "Because they are completely managed by the senior citizens", "B": "Because they are completely managed by the women", "C": "Because they are completely managed by the differently abled persons", "D": "Because they are completely managed by the third gender people"}, "correct": "C", "explanation": "MITTI Cafés are famous for being run entirely by differently-abled (specially-abled) staff, promoting inclusion and self-reliance.", "subject": "Current Affairs", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Central Government in its Union Budget 2023-24 adopted seven priorities of the Government, these 7 priorities are named as", "options": {"A": "Saptadev", "B": "Saptarishi", "C": "Saat Vachan", "D": "Saptadwar"}, "correct": "B", "explanation": "The Union Budget 2023-24 named its seven priority areas 'Saptarishi' — inclusive development, infrastructure, green growth, youth power, financial sector, etc.", "subject": "Economy", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "With reference to \"ANNA DARPAN\" project consider the following statements: (a) It is initiated by the Ministry of Agriculture and Farmer's Welfare Government of India (b) Its objective is to modernise the Supply Chain Management System (c) It is also known as 'Depot Online system' (d) It will not cover its operations at Mandis, Mills and Depots", "options": {"A": "Only (a), (b) and (d)", "B": "Only (b) and (c)", "C": "Only (a), (c) and (d)", "D": "None of the above"}, "correct": "B", "explanation": "Anna Darpan was initiated by the Food Corporation of India (FCI), not the Agriculture Ministry, and it does cover Mandis/Mills/Depots — so only (b) and (c) are correct.", "subject": "Current Affairs", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Which of the following is not a tribe of middle Indian region?", "options": {"A": "Baigas", "B": "Kadars", "C": "Muria", "D": "Kharia"}, "correct": "B", "explanation": "Kadar tribe is found in South India (Kerala/Tamil Nadu); Baiga, Muria and Kharia belong to the Middle Indian tribal belt.", "subject": "Geography/Tribes", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "According to Jain Philosophy, the characteristics of Tatva (Reality) is", "options": {"A": "Origination", "B": "Decay", "C": "Permanence", "D": "All of the above"}, "correct": "D", "explanation": "Jain philosophy holds that Tatva (Reality) has three characteristics — Origination, Decay, and Permanence — as per the doctrine of Anekantavada.", "subject": "Philosophy", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Which among the following pair is an example of paramagnetic and ferromagnetic substances?", "options": {"A": "H2O and Fe", "B": "Cu2+ and Gd", "C": "Cr3+ and MnO", "D": "Fe and Cu2+"}, "correct": "B", "explanation": "Cu2+ is paramagnetic while Gd (Gadolinium) is ferromagnetic, making them a correct paramagnetic-ferromagnetic pair.", "subject": "Physics", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Which of the following Constitutional Amendments restricts the total number of Ministers, including the Prime Minister in the Council of Ministers shall not exceed fifteen percent of the total number of members of the House of the People?", "options": {"A": "86th Amendment", "B": "52nd Amendment", "C": "91st Amendment", "D": "73rd Amendment"}, "correct": "C", "explanation": "The 91st Constitutional Amendment Act, 2003 capped the Council of Ministers (Union/State) at 15% of the total members of the Lok Sabha/Assembly.", "subject": "Polity", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Which of the following film won the 96th Academy Award 2024 in the best picture category?", "options": {"A": "The Holdovers", "B": "Barbie", "C": "Oppenheimer", "D": "Anatomy of a Fall"}, "correct": "C", "explanation": "'Oppenheimer', directed by Christopher Nolan, won Best Picture at the 96th Academy Awards (2024), among 7 total Oscars.", "subject": "Current Affairs", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Where is Devnimori Stupa situated?", "options": {"A": "Andhra Pradesh", "B": "Chhattisgarh", "C": "Rajasthan", "D": "Gujarat"}, "correct": "D", "explanation": "Devnimori Stupa, an important Gupta-era Buddhist site, is located in Aravalli district, Gujarat.", "subject": "History/Art", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "What is the maximum limit of loan at present, provided under the Prime Minister Mudra Yojana?", "options": {"A": "Rupees 10 Lakh", "B": "Rupees 15 Lakh", "C": "Rupees 20 Lakh", "D": "Rupees 25 Lakh"}, "correct": "A", "explanation": "At the time of this exam (Feb 2024), the maximum loan limit under PM Mudra Yojana (Tarun category) was Rs. 10 lakh (later enhanced to Rs. 20 lakh in Budget 2024-25, presented after this exam).", "subject": "Economy", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Which of the following State was the highest iron-ore producing State in the year 2023-24 in India?", "options": {"A": "Odisha", "B": "Karnataka", "C": "Chhattisgarh", "D": "Jharkhand"}, "correct": "A", "explanation": "Odisha has traditionally been India's largest iron-ore producing state, including in FY 2023-24.", "subject": "Economy/Geography", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "\"Khaltahi dialect\" is spoken mainly in Chhattisgarh's", "options": {"A": "In the Western border area of Chhattisgarh", "B": "In the Eastern frontier area of Chhattisgarh", "C": "In the Southern part of Chhattisgarh", "D": "In the Northern part of Chhattisgarh"}, "correct": "D", "explanation": "The Khaltahi dialect (a sub-dialect of Chhattisgarhi) is mainly spoken in the northern part of Chhattisgarh, around Surguja.", "subject": "CG GK", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "The primary sector of Chhattisgarh State includes", "options": {"A": "Animal Husbandry, Mining, Fishing", "B": "Animal Husbandry, Construction, Forestry", "C": "Railways, Trade, Storage", "D": "All of the above"}, "correct": "A", "explanation": "The primary sector covers direct use of natural resources: Animal husbandry, mining and fishing fall in this category.", "subject": "Economy", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Who was the publisher of the Hindi literary magazine \"Chhattisgarh Mitra\"?", "options": {"A": "Madhavrao Sapre", "B": "Raghuvir Prasad", "C": "Pyarelal Gupta", "D": "Gokul Prasad"}, "correct": "A", "explanation": "'Chhattisgarh Mitra', the first Hindi literary magazine of Chhattisgarh, was published by Madhavrao Sapre from Rajnandgaon in 1900.", "subject": "CG GK/Literature", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "In context to Constitution of India which statement is correct?", "options": {"A": "Article 243(A) – Constitution of Panchayats", "B": "Article 243(B) – Gram Sabha", "C": "Article 243(C) – Composition of Panchayat", "D": "None of the above"}, "correct": "B", "explanation": "Article 243(B) provides for the Gram Sabha; 243(A) deals with Gram Sabha itself in some numbering while 243(C) deals with composition of Panchayats — the correct match given is 243(B)-Gram Sabha.", "subject": "Polity", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Which tribe is called the most tattoo loving tribe?", "options": {"A": "Pando", "B": "Baiga", "C": "Bhunjia", "D": "Kamar"}, "correct": "B", "explanation": "The Baiga tribe of Chhattisgarh/Madhya Pradesh is known as the most tattoo (Godna) loving tribe.", "subject": "CG Tribes", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "On which special tithi/date grains are sown in small baskets for the festival of 'Bhojali'?", "options": {"A": "Kwar Shukla Paksha Dwitiya", "B": "Chaitra Shukla Paksha Dwitiya", "C": "Shravan Shukla Paksha Panchami", "D": "Bhadra Krishna Paksha Pratipada"}, "correct": "C", "explanation": "Bhojali seeds are traditionally sown on Shravan Shukla Paksha Panchami (in the month of Shravan).", "subject": "CG Culture", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "During Kalchuri rule which one of the following garh was a part of Chhattisgarh (36 garh)?", "options": {"A": "Vrindavan garh", "B": "Semariya garh", "C": "Pahad garh", "D": "Chitru garh"}, "correct": "C", "explanation": "'Pahad Garh' was one of the 36 garhs (forts/administrative units) that constituted Chhattisgarh during Kalchuri rule.", "subject": "CG History", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Who is eligible for \"Stand up India Scheme\" in Chhattisgarh?", "options": {"A": "Scheduled Caste", "B": "Scheduled Tribe", "C": "Women Entrepreneurs", "D": "All of the above"}, "correct": "D", "explanation": "Stand-Up India Scheme aims to promote entrepreneurship among SC, ST, and Women entrepreneurs — hence all of the above.", "subject": "Economy", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Answer of the Chhattisgarhi puzzle \"Beech Tariya Ma Kanchan Thari\" is", "options": {"A": "Jaamun leaf", "B": "Neem leaf", "C": "Beetle leaf", "D": "Lotus leaf"}, "correct": "D", "explanation": "The riddle 'a golden plate in the middle of the pond' refers to the round floating Lotus leaf ('Purain Patta').", "subject": "CG Culture", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Match the following Mobile Apps List-I of E-Governance with the concerned institutions/departments List-II of the State of Chhattisgarh: (a) Samadhan (b) FARMS (c) CGMMTB (d) CGPURC -- (i) Agriculture (ii) Private Universities (iii) Police (iv) School Education", "options": {"A": "(i)(ii)(iii)(iv)", "B": "(ii)(iii)(iv)(i)", "C": "(iii)(i)(iv)(ii)", "D": "(iv)(ii)(i)(iii)"}, "correct": "C", "explanation": "Samadhan-Police(iii), FARMS-Agriculture(i), CGMMTB-School Education(iv), CGPURC-Private Universities(ii).", "subject": "CG Governance", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Chhattisgarh District Mineral Institute Trust Rule 2015 has been notified by the State Government", "options": {"A": "January 2015", "B": "December 2015", "C": "April 2015", "D": "November 2015"}, "correct": "B", "explanation": "The Chhattisgarh District Mineral Institute Trust Rules were notified in December 2015.", "subject": "CG Mining", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "In which of the following districts Beryl mineral is found?", "options": {"A": "Korba", "B": "Raigarh", "C": "Jashpur", "D": "Raipur"}, "correct": "C", "explanation": "Beryl mineral deposits (a beryllium ore) are mainly found in Jashpur district of Chhattisgarh.", "subject": "CG Geography", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Among one of the special tribes of Chhattisgarh which of the following festival is related to animals?", "options": {"A": "Beesu", "B": "Choura Pooja", "C": "Sohrai", "D": "Dussehra"}, "correct": "C", "explanation": "Sohrai is a festival related to cattle/animal worship, celebrated among Chhattisgarh's tribal communities linked to agriculture and livestock.", "subject": "CG Tribes", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Which content is mostly used in 'Shisal Craft'?", "options": {"A": "Plant", "B": "Bottle gourd", "C": "Seashell", "D": "Soil"}, "correct": "B", "explanation": "'Shisal Shilp' primarily uses the dried Bottle Gourd (Lauki), carved into artistic and utility items.", "subject": "CG Craft", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Article 243(J) of the Indian Constitution is related to", "options": {"A": "Constitution of Finance Commission to review financial position", "B": "Audit of Accounts of Panchayats", "C": "Election of Panchayats", "D": "None of the above"}, "correct": "B", "explanation": "Article 243(J) deals with the audit of accounts of Panchayats.", "subject": "Polity", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "In November 1933, Mahatma Gandhi visited Durg (Chhattisgarh) along with a freedom fighter and stayed at his residence. Choose the correct name of the freedom fighter from the following.", "options": {"A": "Ghanshyam Singh Gupta", "B": "Ratnakar Jha", "C": "Khubchand Baghel", "D": "Madhavrao Sapre"}, "correct": "A", "explanation": "Mahatma Gandhi stayed at the residence of freedom fighter Ghanshyam Singh Gupta during his November 1933 visit to Durg.", "subject": "CG History", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Which University of Chhattisgarh has received A++ grade from NAAC?", "options": {"A": "Guru Ghasidas Central University", "B": "Sant Gahira Guru University", "C": "Pandit Ravishankar Shukla University", "D": "Khairagarh Music and Arts University"}, "correct": "A", "explanation": "Guru Ghasidas Vishwavidyalaya (Central University), Bilaspur, has received an A++ grade from NAAC — the first university in Chhattisgarh to do so.", "subject": "CG Education", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "As per the Chhattisgarh State budget 2024-25 the focus of economic development is", "options": {"A": "GYAN", "B": "VIGYAN", "C": "PRAGYAN", "D": "PRAMAN"}, "correct": "A", "explanation": "The Chhattisgarh State Budget 2024-25 centred its economic development focus around 'GYAN' — technology-based reforms, capital expenditure, and services sector growth.", "subject": "CG Economy", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Where is tourist spot \"Samat Sarna\" located?", "options": {"A": "Biharpur", "B": "Dipadeeh", "C": "Pujaripali", "D": "Kunkuri"}, "correct": "D", "explanation": "Samat Sarna, a place of religious and cultural importance for tribal communities, is located in Kunkuri, Chhattisgarh.", "subject": "CG Tourism", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "\"Shikar Devi\" is mainly related to which tribe?", "options": {"A": "Kamar", "B": "Baiga", "C": "Oraon", "D": "Bhatra"}, "correct": "B", "explanation": "'Shikar Devi' is a principal deity of the Baiga tribe, worshipped as the goddess of hunting and wildlife.", "subject": "CG Tribes", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "What is the position of Chhattisgarh in India in linking forest ecosystem with Green Gross Domestic Product?", "options": {"A": "First", "B": "Second", "C": "Third", "D": "Fourth"}, "correct": "A", "explanation": "Chhattisgarh was the first state in India to link forest ecosystem services with Green GDP.", "subject": "CG Environment", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Which of the following dialect is not a tribal dialect of Chhattisgarh?", "options": {"A": "Halbi", "B": "Khadiya", "C": "Pando", "D": "None of the above"}, "correct": "D", "explanation": "Halbi, Khadiya and Pando are all recognised tribal dialects of Chhattisgarh, so none of them is excluded.", "subject": "CG Culture", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "The Central Government has announced the opening of first lithium mine of India in which of the following districts of Chhattisgarh?", "options": {"A": "Bastar", "B": "Raigarh", "C": "Korba", "D": "Janjgir-Champa"}, "correct": "C", "explanation": "India's first lithium mine (Katghora block) was announced in Korba district, Chhattisgarh, following GSI confirmation of reserves.", "subject": "CG Mining", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "In 1920 at Rajnandgaon, the mill workers striked for 37 days who led it?", "options": {"A": "Vamanrao Lakhe", "B": "Deendayal Singh", "C": "Khubchand Baghel", "D": "None of these"}, "correct": "A", "explanation": "The 1920 Rajnandgaon mill workers' 37-day strike was led by Vamanrao Lakhe.", "subject": "CG History", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "With reference to the Chhattisgarh Panchayat Raj Act, 1993, match the List-I with List-II and select the correct answer: (a) Section-83 (b) Section-89 (c) Section-84 (d) Section-88 -- (i) Inquiry into affairs of Panchayat (ii) Inspection of works of Panchayats (iii) Power of State Govt in regard to relief in taxes (iv) Liability of Panch etc. for loss and mis-appropriation", "options": {"A": "(i)(ii)(iii)(iv)", "B": "(iv)(iii)(ii)(i)", "C": "(iii)(iv)(i)(ii)", "D": "(iii)(iv)(ii)(i)"}, "correct": "A", "explanation": "Section 83-Inquiry into affairs of Panchayat(i); Section 89-Inspection of works(ii); Section 84-Power of State Govt in regard to relief in taxes(iii); Section 88-Liability for loss/misappropriation(iv).", "subject": "CG Polity", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Which of the following soil has the lowest pH value?", "options": {"A": "Bhatha soil", "B": "Dorsa soil", "C": "Matasi soil", "D": "Kanhar soil"}, "correct": "A", "explanation": "Bhatha soil is acidic in nature and has the lowest pH value among Chhattisgarh's soil types.", "subject": "CG Geography", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "\"Maa Bamleshwari Devi\" temple, Dongargarh is being developed under which scheme?", "options": {"A": "Pradhan Mantri Adarsh Gram Yojana", "B": "Prasad Yojana", "C": "Sansad Adarsh Gram Yojana", "D": "None of the above"}, "correct": "B", "explanation": "The Maa Bamleshwari Devi temple at Dongargarh is being developed under the PRASAD Yojana (Pilgrimage Rejuvenation and Spiritual Augmentation Drive).", "subject": "CG Tourism", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "In Chhattisgarh traditional headgear (Maur) worn by the bride and bridegroom during marriages are made from the leaves of which tree?", "options": {"A": "Chhind or Chhin", "B": "Kaner", "C": "Bamboo", "D": "None of the above"}, "correct": "A", "explanation": "The traditional 'Maur/Manoor' headgear worn during Chhattisgarhi weddings is made from the leaves of the Chhind (Date Palm) tree.", "subject": "CG Culture", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "With reference to the Chhattisgarh Panchayat Raj Act, 1993, match the List-I with List-II: (a) Punishment for illegal colonization (b) Grant in aid to Panchayat (c) Function of Chief Executive Officer and Secretary (d) District Panchayat Raj Fund -- (i) Section-72 (ii) Section-61(d) (iii) Section-76 (iv) Section-64", "options": {"A": "(i)(ii)(iii)(iv)", "B": "(ii)(iii)(iv)(i)", "C": "(ii)(iv)(i)(iii)", "D": "None of the above"}, "correct": "A", "explanation": "Punishment for illegal colonization-Section 72(i); Grant in aid-Section 61(d)(ii); Function of CEO/Secretary-Section 76(iii); District Panchayat Raj Fund-Section 64(iv).", "subject": "CG Polity", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Where is Kanthi Deval Temple located?", "options": {"A": "Maheshpur", "B": "Ratanpur", "C": "Fingeshwar", "D": "Sihawa"}, "correct": "B", "explanation": "Kanthi Deval Temple, an ancient Kalchuri-era temple, is located in Ratanpur, Chhattisgarh.", "subject": "CG History", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Which is the hottest region of Mahanadi Basin?", "options": {"A": "Raigarh", "B": "Janjgir-Champa", "C": "Korba", "D": "Raipur"}, "correct": "D", "explanation": "Raipur is the hottest region of the Mahanadi Basin, often reaching around 45°C in summer.", "subject": "CG Geography", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Who has done the Chhattisgarhi poetic translation \"Bhakha Ke Anjor\" (of Gurudev Rabindranath Tagore's Geetanjali)?", "options": {"A": "Suchi Bhavi", "B": "Sudha Verma", "C": "Sarla Sharma", "D": "Savita Pathak"}, "correct": "B", "explanation": "'Bhakha Ke Anjor', the Chhattisgarhi translation of Tagore's Geetanjali, was done by Sudha Verma.", "subject": "CG Literature", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Rice blast disease is a _____ disease.", "options": {"A": "Fungal", "B": "Bacterial", "C": "Nutritional", "D": "All of the above"}, "correct": "A", "explanation": "Rice blast disease is caused by the fungus Magnaporthe oryzae, making it a fungal disease.", "subject": "Agriculture", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Name the freedom fighter of Chhattisgarh who was imprisoned along with his wife Rajkunwar Devi in Nagpur Central Jail for 6 months.", "options": {"A": "Pt. Ravishankar Shukla", "B": "Khubchand Baghel", "C": "Pyarelal Singh", "D": "Barrister Chedilal"}, "correct": "C", "explanation": "Freedom fighter Pyarelal Singh, along with his wife Rajkunwar Devi, was imprisoned in Nagpur Central Jail for six months during the freedom struggle.", "subject": "CG History", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "With whose cooperation NTPC (National Super Thermal Power Centre) was established in Korba in the year 1982-83?", "options": {"A": "World Bank", "B": "Asia Development Bank", "C": "State Bank of India", "D": "Grant by Central Government"}, "correct": "A", "explanation": "NTPC's Korba plant was established in 1982-83 with the cooperation/assistance of the World Bank.", "subject": "CG Economy", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Which of the following river is the right bank tributary of river Mahanadi?", "options": {"A": "Ebb", "B": "Seonath", "C": "Tel", "D": "Mand"}, "correct": "B", "explanation": "The Seonath (Shivnath) river is a right-bank tributary of the Mahanadi; Ib, Tel and Mand are left-bank tributaries.", "subject": "CG Geography", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Which of the following is not a hybrid variety of wheat developed by the Indira Gandhi Krishi Vishwavidyalaya, Raipur?", "options": {"A": "Kanishka", "B": "Ratan", "C": "Indira Sona", "D": "Arpa"}, "correct": "D", "explanation": "'Arpa' is a river of Chhattisgarh, not a wheat variety; Kanishka, Ratan and Indira Sona are wheat varieties developed by IGKV Raipur.", "subject": "Agriculture", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "According to census 2011 total active (working) population of the State of Chhattisgarh is", "options": {"A": "121,80,225", "B": "71,33,866", "C": "100,63,114", "D": "None of the above"}, "correct": "A", "explanation": "As per Census 2011, Chhattisgarh's total active/working population was 1,21,80,225.", "subject": "CG Demography", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "The Tribes of Chhattisgarh obtain black colour for tattoo making from which tree?", "options": {"A": "Sakhua", "B": "Karam", "C": "Bamboo", "D": "Khurai"}, "correct": "A", "explanation": "Tribal communities of Chhattisgarh obtain the black colour used for Godna (tattooing) from the Sakhua (Sal) tree.", "subject": "CG Tribes", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "What is Siropav?", "options": {"A": "Pagri", "B": "Dhoti and Pichhori", "C": "Panhi, Chhakaliya Anga", "D": "All of the above"}, "correct": "D", "explanation": "Siropav/Sirpav refers to the traditional Chhattisgarhi honorific dress set — including Pagri (turban), Dhoti-Pichhori, and Panhi/Chhakaliya Anga — presented as a mark of respect.", "subject": "CG Culture", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Pandit Deendayal Upadhyay Rural Industry Crafts Centre (Bamboo Art Centre) is operated in", "options": {"A": "Jagdalpur", "B": "Dhamtari", "C": "Raipur", "D": "Bilaspur"}, "correct": "A", "explanation": "The Pt. Deendayal Upadhyay Gramodyog Shilp Kendra (Bamboo Art Centre) is operated in Jagdalpur.", "subject": "CG Craft", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "The meaning of Chhattisgarhi idiom \"Aankhee Karuwana\" is", "options": {"A": "To be cute", "B": "To cheat", "C": "To sleep", "D": "To get angry"}, "correct": "C", "explanation": "The Chhattisgarhi idiom 'Aankhee Karuwana' means to feel sleepy / to sleep.", "subject": "CG Language", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "The Fertilizer Corporation of India has established coal-based chemical fertilizer plant in which of the following districts of Chhattisgarh?", "options": {"A": "Raigarh", "B": "Korba", "C": "Raipur", "D": "Durg"}, "correct": "B", "explanation": "The Fertilizer Corporation of India (FCI) established a coal-based chemical fertilizer plant in Korba district.", "subject": "CG Industry", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Which original Sections of the Chhattisgarh Municipal Corporation Act, 1956 were amended under the Chhattisgarh Municipal Corporation (Amendment) Ordinance 2024?", "options": {"A": "(a) and (b)", "B": "(b) and (c)", "C": "(c) and (d)", "D": "All of the above"}, "correct": "D", "explanation": "The 2024 Ordinance amended many sections including 5, 9, 11, 11-A, 14, 15, 16, 17, 18, 20, 23-A, 24, 422 and 441 — including all of Sections 9, 11, 24 and 17 mentioned in the options.", "subject": "CG Polity", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Freedom fighter Baba Purushottam Das was related to which place?", "options": {"A": "Kanker", "B": "Khairagarh", "C": "Ratanpur", "D": "Chhuikhadan"}, "correct": "D", "explanation": "Freedom fighter Baba Purushottam Das was associated with Chhuikhadan in Chhattisgarh.", "subject": "CG History", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "In which district of Chhattisgarh Solar Special Economic Zone (SEZ) is being developed?", "options": {"A": "Raipur", "B": "Durg", "C": "Bilaspur", "D": "Rajnandgaon"}, "correct": "D", "explanation": "A major solar energy project/Special Economic Zone with a large battery energy storage system is being developed in Rajnandgaon district.", "subject": "CG Economy", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "Which one of the following is not related to hunting rituals?", "options": {"A": "Phag Sendra", "B": "Bisu Sikror", "C": "Jeth Hunting", "D": "Magh Hunting"}, "correct": "B", "explanation": "'Bisu Sikror' is a traditional agricultural festival marking the new harvest, not a hunting ritual; Phag Sendra, Jeth Hunting and Magh Hunting are hunting-related rituals of Chhattisgarh's tribes.", "subject": "CG Tribes", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "The art and science of cultivating forest crops is known as", "options": {"A": "Silviculture", "B": "Agroforestry", "C": "Arboriculture", "D": "Forestry"}, "correct": "A", "explanation": "Silviculture is the art and science of cultivating and managing forest crops (trees).", "subject": "Forestry", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "From which ancient site of Chhattisgarh has the terracota seal named \"Vedishree\" been found?", "options": {"A": "Malhar", "B": "Tarighat", "C": "Reewa", "D": "Damru"}, "correct": "B", "explanation": "The terracotta seal named 'Vedishree' was found at the Tarighat archaeological site in Chhattisgarh.", "subject": "CG Archaeology", "exam": "CGPSC Prelims Paper-I 2024"}, {"q": "The meaning of Chhattisgarhi saying \"Jaangar Ke Chalat Le\" is", "options": {"A": "To trust yourself", "B": "Defamation", "C": "Live a care-free life", "D": "Being selfish"}, "correct": "A", "explanation": "The Chhattisgarhi proverb 'Jaangar Ke Chalat Le' means relying on one's own effort and capability — i.e., trust in yourself/self-reliance.", "subject": "CG Language", "exam": "CGPSC Prelims Paper-I 2024"}], "2022": [{"q": "Match the following in reference to the organization of Chhattisgarhiya Olympics, 2022: (a) Rajiv Yuva Mitan Club Level (b) Zone Level (c) Block Level (d) Zila Level -- (i) 6-11 Oct 2022 (ii) 27 Oct-10 Nov 2022 (iii) 15-20 Oct 2022 (iv) 17-26 Nov 2022", "options": {"A": "(i)(iii)(ii)(iv)", "B": "(i)(ii)(iii)(iv)", "C": "(i)(iv)(iii)(ii)", "D": "(iii)(ii)(iv)(i)"}, "correct": "A", "explanation": "Club Level ran 6-11 Oct, Block Level 15-20 Oct, Zone Level 27 Oct-10 Nov, and Zila (district) Level 17-26 Nov 2022 — the culminating stage.", "subject": "CG Sports", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "In reference to Chhattisgarhiya Olympics 2022, which statements are true? (i) 14 sports events (ii) Gilli length 10.5 cm in Gilli-Danda (iii) Two referees called 'Susiriya' in Gilli-Danda (iv) Billas was also part of the Olympics", "options": {"A": "(i),(ii),(iii),(iv)", "B": "Only (i),(ii),(iii)", "C": "Only (i),(ii),(iv)", "D": "Only (ii),(iii)"}, "correct": "A", "explanation": "All four statements are correct: 14 traditional sports were included, Gilli length was 10.5 cm, two referees called Susiriya officiated Gilli-Danda, and Billas was part of the individual category events.", "subject": "CG Sports", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Which statements are true about participating countries in the National Tribal Dance Festival, 2022 of Chhattisgarh? (i) Artists of ten countries participated (ii) Togo, Mozambique, Mongolia, Rwanda, Serbia (iii) Indonesia, Maldives, New Zealand, Russia, Egypt (iv) Burundi, Uganda, Senegal, Ethiopia", "options": {"A": "(i),(ii),(iii),(iv)", "B": "Only (i),(ii),(iv)", "C": "Only (i),(iii),(iv)", "D": "Only (i),(ii),(iii)"}, "correct": "D", "explanation": "The 10 participating countries were Mozambique, Mongolia, Togo, Russia, Indonesia, Maldives, Serbia, New Zealand, Rwanda and Egypt — matching statements (i),(ii) and (iii); Burundi, Uganda, Senegal and Ethiopia did not participate.", "subject": "CG Current Affairs", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Match the following Dances and States related to National Tribal Dance Festival, 2022 of Chhattisgarh: (a) Chirag (b) Harun (c) Dholu Kunia (d) Lawa -- (i) Uttarakhand (ii) Lakshadweep (iii) Mizoram (iv) Karnataka", "options": {"A": "(ii)(iv)(i)(iii)", "B": "(i)(ii)(iv)(iii)", "C": "(iii)(i)(iv)(ii)", "D": "(iv)(ii)(i)(iii)"}, "correct": "C", "explanation": "At the festival, Chirag (bamboo dance) was performed by Mizoram artists, Harun by Uttarakhand, Dholu Kunia (Dollu Kunitha) by Karnataka, and Lawa (Lava) by Lakshadweep artists.", "subject": "CG Current Affairs", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Under Mukhyamantri Bhent Mulaqat of Honorable Chief Minister Shri Bhupesh Baghel, following caste/castes was/were announced to be included in Scheduled Tribes during his stay in Dongargarh: (i) Marar (ii) Pardhi (iii) Gond (iv) Santhal", "options": {"A": "Only (i),(ii),(iii)", "B": "Only (iii) and (iv)", "C": "Only (ii)", "D": "Only (ii),(iii) and (iv)"}, "correct": "C", "explanation": "During his Dongargarh visit, CM Bhupesh Baghel announced inclusion of only the Pardhi caste in the Scheduled Tribes list; Gond and Santhal were already recognised STs and Marar was not included.", "subject": "CG Current Affairs", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "How many Vyaktigat Van Adhikar Patras were uploaded to the Bhuiyan Portal up to 4 July, 2022?", "options": {"A": "183604", "B": "283710", "C": "173604", "D": "283502"}, "correct": "B", "explanation": "As per state forest rights monitoring data reported around mid-2022, approximately 2,83,710 individual forest rights patras (Vyaktigat Van Adhikar Patra) had been uploaded to the Bhuiyan portal.", "subject": "CG Current Affairs", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "During Bhent Mulaqat Programme of the Honorable Chief Minister, when was it organized in Rajnandgaon Assembly Constituency?", "options": {"A": "20 November, 2022", "B": "21 November, 2022", "C": "22 November, 2022", "D": "24 November, 2022"}, "correct": "B", "explanation": "The Mukhyamantri Bhent Mulaqat programme was held in Rajnandgaon Assembly Constituency on 21 November 2022.", "subject": "CG Current Affairs", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Which Gauthan was visited by Ex RBI Governor Shri Raghuram Rajan during Godhan Nyay Yojana, 2022?", "options": {"A": "Loharsi", "B": "Thanaud", "C": "Nawagaon (L)", "D": "Chirmi"}, "correct": "B", "explanation": "Former RBI Governor Raghuram Rajan visited the Thanaud Gauthan in Chhattisgarh to review the Godhan Nyay Yojana in 2022.", "subject": "CG Current Affairs", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Match the honours and dignitaries given in Chhattisgarh Rajyotsava, 2022: (a) Pt. Lakhan Lal Mishra Samman (b) Gundadhur Samman (c) Guru Ghasidas Samman (d) Thakur Pyarelal Samman -- (i) Amitesh Mishra (ii) Khemchand Bharti (iii) Ashok Agrawal (iv) Laxmi Prasad Jaiswal", "options": {"A": "(i)(ii)(iii)(iv)", "B": "(iv)(i)(ii)(iii)", "C": "(iii)(iv)(ii)(i)", "D": "(ii)(i)(iii)(iv)"}, "correct": "B", "explanation": "At Rajyotsav 2022, the Pt. Lakhan Lal Mishra Samman, Gundadhur Samman, Guru Ghasidas Samman and Thakur Pyarelal Samman were conferred respectively on Laxmi Prasad Jaiswal, Amitesh Mishra, Khemchand Bharti and Ashok Agrawal.", "subject": "CG Current Affairs", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "As per the Chhattisgarh Budget 2022, Sectorwise Components of GSDP (Current Price) for 2021-22: (a) Agriculture (b) Difference between excise tax (Utpadan Kar) and subsidy (c) Service (d) Industry -- (i) 40% (ii) 7% (iii) 20% (iv) 33%", "options": {"A": "(i)(ii)(iii)(iv)", "B": "(iii)(ii)(iv)(i)", "C": "(iv)(ii)(i)(iii)", "D": "(iv)(ii)(iii)(i)"}, "correct": "B", "explanation": "As per the Chhattisgarh Budget 2022, agriculture contributed about 20% of GSDP, the excise-subsidy difference about 7%, services about 33%, and industry the largest share at about 40%.", "subject": "CG Economy", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Match the following provisions of the Information Technology Act, 2000 regarding e-governance: (a) Legal recognition of records (b) Legal recognition of electronic signatures (c) Use of electronic records/signatures in government and its agencies (d) Publication of rules, regulations etc. in electronic gazette -- (i) Section 5 (ii) Section 4 (iii) Section 8 (iv) Section 6", "options": {"A": "(i)(ii)(iii)(iv)", "B": "(ii)(i)(iv)(iii)", "C": "(iii)(iv)(ii)(i)", "D": "(iv)(iii)(i)(ii)"}, "correct": "B", "explanation": "Under the IT Act 2000: Section 4 gives legal recognition to electronic records, Section 5 to electronic signatures, Section 6 covers their use in government and agencies, and Section 8 covers publication of rules in the electronic gazette.", "subject": "Polity/IT Act", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "G2C in e-governance means:", "options": {"A": "Government to consumer", "B": "Government to citizen", "C": "Government to customer", "D": "Government to corporate"}, "correct": "B", "explanation": "G2C stands for 'Government to Citizen', referring to e-governance services delivered directly by government to citizens.", "subject": "Governance", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Projects under NeGP (National e-Governance Plan) in Chhattisgarh are: (i) State Wide Area Network (ii) Citizen Contact Centre (iii) Capacity Building (iv) Agrisnet & PDS", "options": {"A": "Only (i),(iii)", "B": "Only (i),(iii),(iv)", "C": "Only (i),(ii),(iv)", "D": "(i),(ii),(iii),(iv)"}, "correct": "D", "explanation": "All four — State Wide Area Network, Citizen Contact Centre, Capacity Building, and Agrisnet & PDS — were implemented as NeGP Mission Mode/infrastructure projects in Chhattisgarh.", "subject": "Governance", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Which of the following are right about declared scheduled area in Chhattisgarh? (i) Sarguja—Entire district (ii) Korba—Entire district (iii) Raigarh—Entire district (iv) Jashpur—Entire district", "options": {"A": "(i),(ii),(iii),(iv)", "B": "Only (i),(ii)", "C": "Only (i),(ii),(iii)", "D": "Only (i),(ii),(iv)"}, "correct": "D", "explanation": "Sarguja, Korba and Jashpur are notified as entirely Fifth Schedule (scheduled) areas in Chhattisgarh, while Raigarh is only partially covered under the scheduled area notification.", "subject": "CG Polity", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Match the following regarding institutions/commission of Chhattisgarh: (a) Inauguration of Thakur Pyarelal Gramin Vikas Sansthan (b) Establishment of State Minority Commission (c) Establishment of Adim Jati Anusandhan Evam Prashikshan Sansthan (d) Notification for Establishment of State Urdu Academy -- (i) 2003 (ii) 2005 (iii) 2001 (iv) 2004", "options": {"A": "(i)(ii)(iii)(iv)", "B": "(ii)(iii)(iv)(i)", "C": "(iii)(iv)(i)(ii)", "D": "(iv)(i)(ii)(iii)"}, "correct": "B", "explanation": "As per Chhattisgarh government records, the Thakur Pyarelal Gramin Vikas Sansthan was inaugurated in 2005, the State Minority Commission formed in 2001, the Adim Jati Anusandhan evam Prashikshan Sansthan established in 2004, and the State Urdu Academy notified in 2003.", "subject": "CG Polity", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "According to the British Records, which of the following Tahutdaris was formed by Captain Sandis?", "options": {"A": "Sanjari", "B": "Sirpur", "C": "Simga", "D": "Sihawa"}, "correct": "D", "explanation": "As per British-era records, the Sihawa tahutdari in Chhattisgarh was formed/settled by Captain Sandys.", "subject": "CG History", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Which are right about the organisation of Zila Panchayat in Chhattisgarh? (i) Elected members of the constituency (ii) Every MP whose parliamentary constituency falls fully or partially in the district is part of it (iii) Every elected Rajya Sabha member from Chhattisgarh enrolled as voter in a Gram Panchayat of the district (iv) Members of Lok Sabha/Vidhan Sabha whose constituency falls fully in urban areas", "options": {"A": "(i),(ii),(iii),(iv)", "B": "Only (i),(ii),(iii)", "C": "Only (i),(ii)", "D": "Only (i),(iii),(iv)"}, "correct": "B", "explanation": "Zila Panchayat membership includes directly elected members, MPs representing the district (fully/partially), and qualifying Rajya Sabha members — but excludes members whose Lok Sabha/Vidhan Sabha constituency lies fully in urban areas.", "subject": "CG Polity", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "In Tribal Development Administration, MADA areas are: (i) Baloda Bazar (ii) Nachaniya (iii) Kawardha (iv) Gaurela", "options": {"A": "(i),(ii),(iii),(iv)", "B": "Only (i),(ii),(iv)", "C": "Only (i),(ii),(iii)", "D": "Only (ii),(iii),(iv)"}, "correct": "C", "explanation": "Under Chhattisgarh's Tribal Development Administration, the Modified Area Development Approach (MADA) pockets include Baloda Bazar, Nachaniya and Kawardha.", "subject": "CG Polity", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "What approximate area comes under Tribal Sub-plan of Chhattisgarh, according to Census 2011?", "options": {"A": "78000 sq. km", "B": "88000 sq. km", "C": "98000 sq. km", "D": "108000 sq. km"}, "correct": "B", "explanation": "According to Census 2011-based estimates, roughly 88,000 sq. km of Chhattisgarh's area falls under the Tribal Sub-Plan.", "subject": "CG Geography", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Newly formed district Manendragarh-Chirmiri-Bharatpur lies in which direction of the State?", "options": {"A": "South-East", "B": "West", "C": "North-West", "D": "North"}, "correct": "C", "explanation": "Manendragarh-Chirmiri-Bharatpur district, carved out of the Sarguja/Koriya region, lies in the north-western part of Chhattisgarh.", "subject": "CG Geography", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Rihand and Mand rivers of Chhattisgarh originate from:", "options": {"A": "Chilphi Ghati", "B": "Maikal Hill", "C": "Mainpat", "D": "None of the above"}, "correct": "B", "explanation": "Both the Rihand and Mand rivers of Chhattisgarh originate from the Maikal hill range.", "subject": "CG Geography", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "In which district is 'Madheshwar Pahad' located in Chhattisgarh?", "options": {"A": "Surajpur", "B": "Jashpur", "C": "Sarguja", "D": "Kanker"}, "correct": "B", "explanation": "Madheshwar Pahad, a hill of religious and scenic importance, is located in Jashpur district of Chhattisgarh.", "subject": "CG Geography", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "In Chhattisgarh, maximum Tin deposit occurs in the area:", "options": {"A": "Mainpat", "B": "Maikal Range", "C": "Dandkaranya", "D": "Mahanadi Basin"}, "correct": "A", "explanation": "The maximum reserves of tin ore in Chhattisgarh are found in the Mainpat area of Surguja district.", "subject": "CG Geography", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Which of the following are very low irrigated districts in Chhattisgarh?", "options": {"A": "Durg, Balaud, Baloda Bazar", "B": "Sarguja, Korba, Sukma", "C": "Bijapur, Mungeli, Mahasamund", "D": "Narayanpur, Bilaspur, Gariyaband"}, "correct": "B", "explanation": "Sarguja, Korba and Sukma are among Chhattisgarh's very low-irrigated districts, being largely hilly/forested with limited canal network.", "subject": "CG Geography", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "In which of the following districts was 'Marwa Taap Vidyut Sanyantra' established?", "options": {"A": "Kawardha", "B": "Janjgir-Champa", "C": "Korba", "D": "Sarguja"}, "correct": "C", "explanation": "The Marwa Thermal Power Plant (Marwa Taap Vidyut Sanyantra) is located in Korba district, Chhattisgarh's power hub.", "subject": "CG Economy", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Reasons of maximum sex-ratio in Dantewada and Kondagaon of Dandkaranya are: (i) Higher male death rate (ii) Absence of female feticide (iii) Inaccessible area (iv) Backward area", "options": {"A": "(i) and (iii)", "B": "(i) and (ii)", "C": "(ii) and (iii)", "D": "(ii) and (iv)"}, "correct": "A", "explanation": "The high sex ratio in Dantewada and Kondagaon is attributed to a higher male death rate (due to conflict/hazardous work) and the inaccessible, remote terrain of the region.", "subject": "CG Geography", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Which tree is found in plurality in Sita Nadi area?", "options": {"A": "Bamboo", "B": "Teak", "C": "Mahua", "D": "Sal"}, "correct": "A", "explanation": "The Sita Nadi Wildlife Sanctuary area of Chhattisgarh is characterised by an abundance of Bamboo forests.", "subject": "CG Geography", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "According to the Economic Survey 2021-22 of Chhattisgarh, which sector registered the highest growth rate in 2021-22 at constant prices?", "options": {"A": "Mining and quarrying", "B": "Construction", "C": "Manufacturing", "D": "Services"}, "correct": "C", "explanation": "As per the Chhattisgarh Economic Survey 2021-22, the manufacturing sector registered the highest growth rate at constant prices in 2021-22, reflecting post-pandemic industrial recovery.", "subject": "CG Economy", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "According to the Economic Survey 2021-22 of Chhattisgarh, which sector registered the lowest growth rate in 2021-22 at constant prices?", "options": {"A": "Animal husbandry", "B": "Forestry and logging", "C": "Storage", "D": "Fishing industry"}, "correct": "C", "explanation": "As per the Chhattisgarh Economic Survey 2021-22, the storage sector registered the lowest growth rate at constant prices in 2021-22.", "subject": "CG Economy", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "According to the Chhattisgarh Economic Survey 2021-22, agriculture sector registered average growth rate at constant prices between 2012-13 to 2021-22:", "options": {"A": "5.19 percent", "B": "5.09 percent", "C": "5.21 percent", "D": "5.17 percent"}, "correct": "A", "explanation": "The Chhattisgarh Economic Survey 2021-22 recorded the agriculture sector's average annual growth rate at constant prices over 2012-13 to 2021-22 as approximately 5.19%.", "subject": "CG Economy", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Who is the present Chairman of Chhattisgarh State Scheduled Caste Commission?", "options": {"A": "Dr. Vinod Khandekar", "B": "Shri Ram Ji Bharti", "C": "Smt. Padma Manhar", "D": "Shri K. P. Khande"}, "correct": "B", "explanation": "Shri Ram Ji Bharti served as the Chairman of the Chhattisgarh State Scheduled Caste Commission around this period.", "subject": "CG Polity", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "What is the number of students beneficiaries as on December 2020 under mid-day meal as per Economic Survey of 2021-22 of Chhattisgarh?", "options": {"A": "28.66 lakh students", "B": "28.26 lakh students", "C": "27.97 lakh students", "D": "27.74 lakh students"}, "correct": "A", "explanation": "As per the Chhattisgarh Economic Survey 2021-22, about 28.66 lakh students were mid-day meal beneficiaries as of December 2020.", "subject": "CG Economy", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "According to the Chhattisgarh Budget Estimates 2021-22, the contribution of tax revenue in total revenue receipts in financial year 2021-22 is:", "options": {"A": "61.05 percent", "B": "62.05 percent", "C": "62.15 percent", "D": "62.37 percent"}, "correct": "C", "explanation": "As per the Chhattisgarh Budget Estimates 2021-22, tax revenue contributed about 62.15% of total revenue receipts.", "subject": "CG Economy", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "In the year 2020-21, which oilseed recorded maximum production in Chhattisgarh, according to Chhattisgarh Economic Survey 2021-22?", "options": {"A": "Groundnut", "B": "Til", "C": "Soyabean", "D": "Rai-Sarson (Mustard)"}, "correct": "C", "explanation": "Soyabean recorded the maximum production among oilseeds in Chhattisgarh in 2020-21 as per the Economic Survey 2021-22.", "subject": "CG Economy", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "According to Chhattisgarh Economic Survey 2021-22, the respective share of agriculture, industry and services in GSDP of Chhattisgarh in 2021-22 at constant prices is:", "options": {"A": "16.73%, 50.69%, 32.58%", "B": "16.73%, 50.61%, 32.66%", "C": "16.71%, 50.63%, 32.66%", "D": "16.76%, 50.61%, 32.63%"}, "correct": "B", "explanation": "As per the Chhattisgarh Economic Survey 2021-22, at constant prices agriculture, industry and services contributed approximately 16.73%, 50.61% and 32.66% respectively to the state's GSDP in 2021-22.", "subject": "CG Economy", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Match the Kalchuri rulers of Ratanpur with the places from where their inscriptions/copper plates were found: (a) Prithvi Dev Pratham (b) Gopal Dev (c) Pratap Mall (d) Bahar Sai -- (i) Amoda (ii) Pujari Pali (iii) Balaigarh (iv) Kosgai", "options": {"A": "(i)(ii)(iii)(iv)", "B": "(ii)(i)(iii)(iv)", "C": "(iv)(i)(ii)(iii)", "D": "(iv)(iii)(ii)(i)"}, "correct": "B", "explanation": "Inscriptions of the Kalchuri rulers of Ratanpur were found as follows: Prithvi Dev Pratham at Pujari Pali, Gopal Dev at Amoda, Pratap Mall at Balaigarh, and Bahar Sai at Kosgai.", "subject": "CG History", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Which of the following characteristics is not found in the coins of Kalchuri ruler Ratndev of Ratanpur?", "options": {"A": "Gaj Shardul", "B": "Singh (Lion)", "C": "Gaj Laxmi", "D": "Manavakriti (Human Figure)"}, "correct": "D", "explanation": "The coins of Kalchuri ruler Ratnadev of Ratanpur depict Gaj Shardul, Lion and Gaj Laxmi motifs, but not a human figure (Manavakriti).", "subject": "CG History", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "When did Raghuji dethrone the Kalchuri ruler Raghunath Singh in Ratanpur Rajya and appoint a new administrator?", "options": {"A": "1940", "B": "1741", "C": "1745", "D": "1750"}, "correct": "B", "explanation": "Maratha ruler Raghuji Bhonsle dethroned the last Kalchuri ruler Raghunath Singh of Ratanpur and appointed a new administrator around 1741, bringing Maratha control over Ratanpur.", "subject": "CG History", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Match the following events of Bhoomkaal Revolt of Bastar with their dates: (a) Declaration of Revolt (b) Attack on Kukanar (c) Declaration of Muriya Raj (d) Arrest of Rani Subaran Kunwar -- (i) 4 February, 1910 (ii) 5 March, 1910 (iii) October, 1909 (iv) 7 February, 1910", "options": {"A": "(i)(ii)(iii)(iv)", "B": "(iii)(i)(iv)(ii)", "C": "(iv)(iii)(i)(ii)", "D": "(iii)(iv)(ii)(i)"}, "correct": "B", "explanation": "The Bhoomkaal revolt of Bastar: Muriya Raj was declared in October 1909, the revolt formally declared on 4 February 1910, Rani Subaran Kunwar arrested on 7 February 1910, and Kukanar was attacked on 5 March 1910.", "subject": "CG History", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "When did E. Raghvendra Rao first become the Chief Minister of Central Provinces and Berar?", "options": {"A": "1923", "B": "1927", "C": "1929", "D": "1936"}, "correct": "B", "explanation": "E. Raghvendra Rao first became Chief Minister (then called Premier) of the Central Provinces and Berar in 1927.", "subject": "History", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Match the following Forest Satyagrahas under the Civil Disobedience Movement with dates: (a) Rudri Jungle Satyagraha (b) Podi Jungle Satyagraha (c) Tamora Jungle Satyagraha (d) Pakariya Jungle Satyagraha -- (i) 3 August, 1930 (ii) 9 September, 1930 (iii) 7 October, 1930 (iv) 22 August, 1930", "options": {"A": "(iv)(i)(iii)(ii)", "B": "(i)(ii)(iii)(iv)", "C": "(iv)(i)(ii)(iii)", "D": "(ii)(i)(iii)(iv)"}, "correct": "A", "explanation": "The Forest Satyagrahas in Chhattisgarh during the Civil Disobedience Movement began at Rudri on 22 August 1930, Podi on 3 August 1930, Tamora on 7 October 1930, and Pakariya on 9 September 1930.", "subject": "CG History", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "When did the British Government give Sanad to Mahant Ghasidas of Rajnandgaon State to be the ruler?", "options": {"A": "1861", "B": "1865", "C": "1869", "D": "1872"}, "correct": "A", "explanation": "The British Government issued the Sanad recognising Mahant Ghasidas as ruler of Rajnandgaon State in 1861.", "subject": "CG History", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Vallabhacharya, a famous Saint of the Bhakti Movement, was born in which place in Chhattisgarh?", "options": {"A": "Champaranya", "B": "Giraudpuri", "C": "Ratanpur", "D": "Sirpur"}, "correct": "A", "explanation": "Vallabhacharya, founder of the Pushtimarg tradition, was born at Champaranya near Raipur in Chhattisgarh in 1479.", "subject": "CG History", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "As per the Vayu Puran, what is the mythological name of the Mahanadi river?", "options": {"A": "Chitrotpala", "B": "Nilotpala", "C": "Kanak Nandini", "D": "Mahananda"}, "correct": "A", "explanation": "The Vayu Purana refers to the Mahanadi river by its mythological name 'Chitrotpala'.", "subject": "CG History", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Amongst the following, which of the waterfalls is not situated in Kanger Valley of Bastar?", "options": {"A": "Kudang Khodra", "B": "Jhulan Darha", "C": "Khursel", "D": "Shiv Ganga"}, "correct": "C", "explanation": "Kudang Khodra, Jhulan Darha and Shiv Ganga falls lie within the Kanger Valley National Park of Bastar, while Khursel is not located within the valley.", "subject": "CG Geography", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "'Bali Barab', a festival lasting for three months, is celebrated in which tribe?", "options": {"A": "Bhatra", "B": "Parja", "C": "Gadba", "D": "Halba"}, "correct": "B", "explanation": "'Bali Barab', a three-month long festival, is celebrated by the Parja tribe of Bastar.", "subject": "CG Tribes", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Sohar Song is sung on which occasion?", "options": {"A": "On the occasion of the birth of a child", "B": "On the occasion of Chhathee", "C": "On the occasion of the naming ceremony", "D": "On the occasion of marriage"}, "correct": "A", "explanation": "'Sohar' geet is a traditional folk song sung to celebrate the birth of a child.", "subject": "CG Culture", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Which of the following is the main instrument used in Pandwani Folk Song?", "options": {"A": "Algoja", "B": "Khadtal", "C": "Mandar", "D": "Mohri"}, "correct": "C", "explanation": "The Mandar, a traditional percussion instrument, is the main accompanying instrument used in Pandwani folk singing of Chhattisgarh.", "subject": "CG Culture", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Match Section 'A' with Section 'B': (a) Devar (b) Bharthari (c) Dadaria (d) Phadi -- (i) Pranay Geet (ii) Vyangya and Hasya Geet (iii) Bhiksha Mangte Huye Geet (iv) Vairagya Geet", "options": {"A": "(iv)(iii)(ii)(i)", "B": "(ii)(i)(iv)(iii)", "C": "(i)(iii)(ii)(iv)", "D": "(iii)(iv)(i)(ii)"}, "correct": "C", "explanation": "Devar songs are love songs (Pranay Geet), Bharthari songs express renunciation (Vairagya Geet), Dadaria songs carry witty/humorous themes (Vyangya-Hasya Geet), and Phadi songs are sung while begging alms (Bhiksha Mangte Huye Geet).", "subject": "CG Culture", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "What is the meaning of the Chhattisgarhi word 'Fusar Fusar'?", "options": {"A": "Karaaraa Jabaab Dena", "B": "Kaanaaphoosi Karna", "C": "Havai Baat Karna", "D": "Dikhaava Karna"}, "correct": "B", "explanation": "'Fusar Fusar' in Chhattisgarhi means to whisper (Kaanaaphoosi Karna).", "subject": "CG Language", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Correctly match the following: (a) Paleolithic Age (b) Mesolithic Age (c) Neolithic Age (d) Chalcolithic Age -- (i) Bhimbetka Caves (ii) Burzahom (iii) Banas Valley (iv) Sohan/Soan River Valley", "options": {"A": "(i)(ii)(iv)(iii)", "B": "(iv)(i)(ii)(iii)", "C": "(iv)(ii)(i)(iii)", "D": "(i)(iv)(iii)(ii)"}, "correct": "B", "explanation": "The Soan/Sohan river valley is the classic Paleolithic site; Bhimbetka caves are famous for Mesolithic rock art; Burzahom (Kashmir) is a key Neolithic site; and the Banas valley (Ahar culture) represents the Chalcolithic age.", "subject": "History", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Based on findings of excavation of Harappan Civilization, what are not true? (i) Same size of bricks were used for all kinds of constructions (ii) Mostly all houses were single storey (iii) Main roads were on average ten meters in width", "options": {"A": "(i) and (ii)", "B": "(ii) and (iii)", "C": "(i) and (iii)", "D": "(i), (ii) and (iii)"}, "correct": "A", "explanation": "Excavations show different brick shapes/sizes were used for different purposes (e.g., wedge-shaped bricks for wells), and evidence of staircases suggests many houses had upper storeys — so both (i) and (ii) are not strictly true.", "subject": "History", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Correctly match the following: Buddhist Councils and Presidents: (a) First Buddhist Council (b) Second Buddhist Council (c) Third Buddhist Council (d) Fourth Buddhist Council -- (i) Vasumitra (ii) Mahakashyapa (iii) Sabakami (iv) Moggaliputta Tissa", "options": {"A": "(i)(ii)(iii)(iv)", "B": "(ii)(iv)(iii)(i)", "C": "(ii)(iii)(i)(iv)", "D": "(ii)(iii)(iv)(i)"}, "correct": "D", "explanation": "The First Council was presided by Mahakashyapa, Second by Sabakami, Third by Moggaliputta Tissa, and Fourth (Kashmir) by Vasumitra.", "subject": "History", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "What is not true in relation to Vardhamana Mahavir?", "options": {"A": "He is considered to be 24th and last Tirthankara", "B": "His mother was sister of Licchavi's king Chetaka", "C": "He did not marry in his lifetime", "D": "He left his body in 527 BCE at Pavapuri near Patna"}, "correct": "C", "explanation": "Per Svetambara tradition, Mahavir did marry (to Yashoda) and had a daughter, so the claim that he never married is not true; the other statements about him are accurate.", "subject": "History", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Which of the following is not written by Varahamihira?", "options": {"A": "Panchasiddhantika", "B": "Brihat Samhita", "C": "Brihat Jataka", "D": "Amarkosha"}, "correct": "D", "explanation": "Panchasiddhantika, Brihat Samhita and Brihat Jataka were composed by Varahamihira; Amarkosha was written by Amarasimha.", "subject": "History", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "What is/are not true about King Mihir Bhoja? (i) He was the son of Nagabhatta-II (ii) Kannauj was the capital of his kingdom (iii) Arab traveller Al-Masudi gave him the name of King Baura", "options": {"A": "(i) and (ii)", "B": "Only (i)", "C": "(ii) and (iii)", "D": "Only (iii)"}, "correct": "B", "explanation": "Mihir Bhoja was actually the son of Ramabhadra and grandson of Nagabhatta II, not directly his son — making statement (i) incorrect, while (ii) and (iii) are accurate.", "subject": "History", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Which of the following is/are true about Vasco Da Gama? (i) Zamorin was ruler of Calicut during his 1498 trip (ii) In his first trip he stayed approximately one year in India (iii) He revisited India in 1501", "options": {"A": "(i), (ii) and (iii)", "B": "(i) and (ii)", "C": "(i) and (iii)", "D": "Only (i)"}, "correct": "D", "explanation": "Only statement (i) is accurate; Vasco da Gama's first stay in India (1498) lasted only a few months, not a year, and his second voyage to India began in 1502, not 1501.", "subject": "History", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Correctly match the following: (a) Afonso de Albuquerque (b) Nuno da Cunha (c) Pedro Alvares Cabral (d) Francisco de Almeida -- (i) Change of Portuguese headquarter from Cochin to Goa (ii) Arrival in India in September AD 1500 (iii) Blue Water Policy (iv) Acquiring Goa in 1510", "options": {"A": "(i)(ii)(iv)(iii)", "B": "(iv)(i)(ii)(iii)", "C": "(i)(iv)(ii)(iii)", "D": "(iv)(i)(iii)(ii)"}, "correct": "B", "explanation": "Afonso de Albuquerque acquired Goa in 1510, Nuno da Cunha shifted the Portuguese headquarters from Cochin to Goa, Pedro Alvares Cabral arrived in India in September 1500, and Francisco de Almeida pursued the Blue Water Policy.", "subject": "History", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "What is/are true about the priests sent to Akbar's court by Goa Church Authorities in 1595 to resolve his curiosities about Christianity? (i) It was the third mission sent to Akbar's court (ii) This mission met Akbar in Lahore (iii) Antonio Monserrate was included in this mission", "options": {"A": "Only (i)", "B": "(i) and (ii)", "C": "(i) and (iii)", "D": "(i), (ii) and (iii)"}, "correct": "B", "explanation": "The 1595 mission was indeed the third Jesuit mission and met Akbar in Lahore; however, Antonio Monserrate had been part of the first mission (1580), not this third one.", "subject": "History", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Match the following Dutch factories with their years of establishment: (a) Bimlipatam (b) Karaikal (c) Cochin (d) Chinsura -- (i) 1653 (ii) 1645 (iii) 1641 (iv) 1663", "options": {"A": "(i)(ii)(iv)(iii)", "B": "(iii)(ii)(iv)(i)", "C": "(iii)(iv)(ii)(i)", "D": "(i)(ii)(iii)(iv)"}, "correct": "B", "explanation": "The Dutch established their factory at Bimlipatam in 1641, Karaikal in 1645, captured Cochin from the Portuguese in 1663, and set up Chinsura in Bengal in 1653.", "subject": "History", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "What is/are not true in relation to 'Battle of Ambur'? (i) Fought in 1752 (ii) Armies of Muzaffarganj, Chanda Sahib and French fought together against Anwar-ud-din (iii) Anwar-ud-din's army faced defeat", "options": {"A": "(ii) and (iii)", "B": "(i) and (iii)", "C": "(i) and (ii)", "D": "Only (i)"}, "correct": "D", "explanation": "The Battle of Ambur was actually fought in 1749, not 1752; the coalition of Muzaffarjang, Chanda Sahib and the French did defeat and kill Anwar-ud-din, so statements (ii) and (iii) are correct.", "subject": "History", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Which of the following is/are not true? (i) Kilich Khan was also known as Mubariz Khan (ii) Nizam-ul-Mulk defeated Mubariz Khan in Battle of Shakar Kheda (iii) Julfikar Khan gave Nizam-ul-Mulk the title of Asaf-Jah", "options": {"A": "Only (i)", "B": "(i) and (iii)", "C": "(ii) and (iii)", "D": "(i), (ii) and (iii)"}, "correct": "B", "explanation": "Kilich Khan (Chin Qilich Khan) was Nizam-ul-Mulk's own name, not Mubariz Khan (his rival, whom he defeated at Shakar Kheda in 1724); and it was Emperor Muhammad Shah, not Zulfiqar Khan, who conferred the title Asaf Jah on him.", "subject": "History", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Which of the following is/are not true in relation to the Congress Annual Session in 1927? (i) Presided by Dr. M.A. Ansari (ii) Passed a resolution against sending Indian Army to fight war in China and Japan (iii) Resolution on 'Purna Swaraj' was adopted", "options": {"A": "(i) and (ii)", "B": "(ii) and (iii)", "C": "Only (ii)", "D": "None of the above"}, "correct": "D", "explanation": "The 1927 Madras Congress session, presided over by Dr. M.A. Ansari, did pass a resolution opposing the use of Indian troops in China/Japan; the 'Purna Swaraj' resolution, however, was adopted later at the 1929 Lahore session, not 1927 — making statement (iii) the only inaccurate one, so the listed 'not true' combinations don't correctly capture it.", "subject": "History", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "What are true about plasma state? (i) Particles in this state are in ionic state (ii) Light in the LED bulb is related to plasma state (iii) Sunlight is also an example of plasma state", "options": {"A": "(i), (ii) and (iii)", "B": "(i) and (ii)", "C": "(i) and (iii)", "D": "None of the above"}, "correct": "C", "explanation": "Plasma consists of ionised particles, and the Sun is a well-known natural example of plasma; LED light, however, is produced by solid-state electroluminescence, not plasma.", "subject": "Physics", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Correctly match the following Elements with Valency: (a) Silicon (b) Fluorine (c) Aluminium (d) Sulphur -- (i) 1 (ii) 2 (iii) 3 (iv) 4", "options": {"A": "(iv)(iii)(ii)(i)", "B": "(iv)(i)(iii)(ii)", "C": "(iii)(iv)(i)(ii)", "D": "(iii)(iv)(ii)(i)"}, "correct": "B", "explanation": "Silicon has a valency of 4, Fluorine 1, Aluminium 3, and Sulphur (commonly) 2.", "subject": "Chemistry", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Which of the following statements are true? (i) Small pores in epidermis of leaf are called stomata (ii) Guard cells in stomata help exchange gases with atmosphere (iii) Transpiration takes place through stomata", "options": {"A": "(i) and (ii)", "B": "(i) and (iii)", "C": "(ii) and (iii)", "D": "(i), (ii) and (iii)"}, "correct": "D", "explanation": "All three statements about stomata — their identity, the role of guard cells in gas exchange, and their role in transpiration — are correct.", "subject": "Biology", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Arrange the following carbon compounds in decreasing order of their melting points:", "options": {"A": "Ethanol > Chloroform > Acetic acid > Methane", "B": "Chloroform > Acetic acid > Ethanol > Methane", "C": "Acetic acid > Chloroform > Methane > Ethanol", "D": "Acetic acid > Chloroform > Ethanol > Methane"}, "correct": "D", "explanation": "Melting points: Acetic acid (~16.6°C) > Chloroform (~-63°C) > Ethanol (~-114°C) > Methane (~-182°C).", "subject": "Chemistry", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "What is/are not true among the following? (i) Audible range of sound for humans is approximately 20 Hz to 10 kHz (ii) Sound waves with frequencies higher than 10 kHz are called ultrasound (iii) In earthquakes, ultrasounds are produced before main shock waves", "options": {"A": "(i) and (ii)", "B": "(i) and (iii)", "C": "(i), (ii) and (iii)", "D": "Only (iii)"}, "correct": "A", "explanation": "The standard human audible range is 20 Hz to 20 kHz (not 10 kHz), and correspondingly ultrasound is defined as sound above 20 kHz, not 10 kHz — making both (i) and (ii) inaccurate as stated.", "subject": "Physics", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "In August 1932, the British Prime Minister announced the scheme for representation of depressed classes, called the Communal Award. Gandhiji started a fast unto death in opposition to this scheme in which jail?", "options": {"A": "Ahmednagar Jail", "B": "Bombay Central Jail", "C": "Yerawada Jail", "D": "None of the above"}, "correct": "C", "explanation": "Gandhi undertook his 'epic fast' against the Communal Award at Yerawada Central Jail, Pune, in September 1932.", "subject": "History", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Read the following statements and choose the correct option: (i) For passengers flying at very high altitudes, sky appears dark (ii) Scattering is not prominent at such heights", "options": {"A": "(i) and (ii) both true, (ii) correctly explains (i)", "B": "(i) and (ii) both true, but (ii) is not correct reasoning of (i)", "C": "(i) is correct and (ii) is incorrect", "D": "(i) is incorrect and (ii) is correct"}, "correct": "A", "explanation": "At high altitudes the atmosphere is thin, so scattering of sunlight is minimal, which correctly explains why the sky appears dark to high-altitude passengers.", "subject": "Physics", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "What is not true in relation to the Charter Act, 1813?", "options": {"A": "It allowed Christian Missionaries to come to India for enlightenment", "B": "It asserted the sovereignty of the British Crown over the company's territories in India", "C": "This Act abolished the trade monopoly of the East India Company including its tea trade", "D": "None of the above"}, "correct": "C", "explanation": "The Charter Act of 1813 ended the Company's monopoly over trade with India in general, but its monopoly over tea trade and trade with China continued until the Charter Act of 1833.", "subject": "History", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "What are true about the Constituent Assembly? (i) First meeting held on 9th December, 1946 (ii) Its first permanent President was Dr. Sachchidanand Sinha (iii) Muslim League boycotted the first meeting", "options": {"A": "(i), (ii) and (iii)", "B": "(i) and (iii)", "C": "(i) and (ii)", "D": "None of the above"}, "correct": "B", "explanation": "The Assembly's first meeting was on 9 December 1946, which the Muslim League boycotted; however, Dr. Sachchidanand Sinha only served as the temporary/interim Chairman on the first day — Dr. Rajendra Prasad was later elected the permanent President.", "subject": "Polity", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "By which Constitutional Amendment was the minimum voting age reduced from 21 years to 18 years in 1989?", "options": {"A": "61st Constitutional Amendment Act", "B": "62nd Constitutional Amendment Act", "C": "63rd Constitutional Amendment Act", "D": "64th Constitutional Amendment Act"}, "correct": "A", "explanation": "The 61st Constitutional Amendment Act, 1988 (effective 1989) reduced the minimum voting age from 21 to 18 years.", "subject": "Polity", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Correctly match the following: (a) Cultural and Educational Rights (b) Right to Constitutional Remedies (c) Right against Exploitation (d) Right to Equality -- (i) Articles 14-18 (ii) Articles 23-24 (iii) Article 32 (iv) Articles 29-30", "options": {"A": "(iv)(iii)(i)(ii)", "B": "(iii)(iv)(ii)(i)", "C": "(iii)(iv)(i)(ii)", "D": "(iv)(iii)(ii)(i)"}, "correct": "D", "explanation": "Cultural and Educational Rights are covered under Articles 29-30, Right to Constitutional Remedies under Article 32, Right against Exploitation under Articles 23-24, and Right to Equality under Articles 14-18.", "subject": "Polity", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "What is/are true among the following? (i) By 73rd and 74th Constitutional Amendments, Three-tier Governance System was introduced (ii) This system was copied from the Constitution of Australia (iii) 74th Constitutional Amendment Act relates to giving constitutional recognition to Panchayats", "options": {"A": "(i), (ii) and (iii)", "B": "(i) and (iii)", "C": "Only (i)", "D": "None of the above"}, "correct": "C", "explanation": "The 73rd and 74th Amendments did introduce a three-tier governance system in India; however, the system was not copied from Australia's constitution, and it is the 74th Amendment that deals with Municipalities, not Panchayats (the 73rd Amendment covers Panchayats) — so only statement (i) is accurate.", "subject": "Polity", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "The 100th Constitutional Amendment Act, 2015 was brought for exchange of territories between India and Bangladesh. What is not true in reference to this?", "options": {"A": "Under this, India transferred 51 enclaves to Bangladesh whereas Bangladesh transferred 111 enclaves to India", "B": "Under this, 6.1 km undemarcated boundary land was demarcated", "C": "Due to this, territories of four States got changed", "D": "None of the above"}, "correct": "A", "explanation": "The actual exchange was the reverse of what is stated: India transferred 111 enclaves to Bangladesh and received 51 enclaves from Bangladesh under the Land Boundary Agreement.", "subject": "Polity", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Who among the following was not the member of the Reorganization Commission formed in 1953, whose recommendations were taken into account for the States Reorganization Act, 1956?", "options": {"A": "Pattabhi Sitaramayya", "B": "Fazl Ali", "C": "K.M. Panikkar", "D": "H.N. Kunzru"}, "correct": "A", "explanation": "The States Reorganisation Commission (1953) comprised Fazal Ali (Chairman), H.N. Kunzru and K.M. Panikkar; Pattabhi Sitaramayya was not a member.", "subject": "Polity", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Provision for Discretionary Grant which may be given by Central Government to States is given under which Article of the Constitution?", "options": {"A": "Article 275", "B": "Article 281", "C": "Article 282", "D": "Article 228"}, "correct": "C", "explanation": "Article 282 empowers the Union and State Governments to make discretionary grants for any public purpose, even outside their normal legislative competence.", "subject": "Polity", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "What is not true in relation to election of President?", "options": {"A": "Provision for process of election of President is described in Article 55", "B": "At nomination a candidate must submit signed list of 50 proposers and 50 seconders", "C": "Value of votes of State Legislature members is based on population of respective States, based on 1971 Census data", "D": "None of the above"}, "correct": "D", "explanation": "All three statements are accurate: Article 55 lays down the election process, nomination requires 50 proposers/seconders, and the value of MLA votes is based on population figures frozen at the 1971 Census.", "subject": "Polity", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "If any member of Parliament is elected for any State Legislature, within how many days must he resign from the State Legislature, otherwise his Parliament membership becomes void?", "options": {"A": "10 days", "B": "14 days", "C": "30 days", "D": "None of the above"}, "correct": "B", "explanation": "A person elected to both Parliament and a State Legislature must resign from the State Legislature within 14 days, failing which their parliamentary seat becomes vacant.", "subject": "Polity", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Arrange the following States in decreasing order of the number of seats in Rajya Sabha:", "options": {"A": "Gujarat > Karnataka > Kerala > Odisha", "B": "Karnataka > Gujarat > Kerala > Odisha", "C": "Karnataka > Gujarat > Odisha > Kerala", "D": "Gujarat > Karnataka > Odisha > Kerala"}, "correct": "C", "explanation": "Rajya Sabha seat allocation: Karnataka (12) > Gujarat (11) > Odisha (10) > Kerala (9).", "subject": "Polity", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Correctly match the following: (a) North-Western Himalayas (b) Himachal and Uttarakhand Himalaya (c) Darjeeling and Sikkim Himalaya (d) Arunachal Himalaya -- (i) Zaskar (ii) Shivalik Range (iii) Namcha Barwa (iv) Lepcha tribe", "options": {"A": "(i)(ii)(iii)(iv)", "B": "(ii)(i)(iii)(iv)", "C": "(ii)(i)(iv)(iii)", "D": "(i)(ii)(iv)(iii)"}, "correct": "D", "explanation": "The Zaskar range lies in the North-Western Himalayas; the Shivalik range runs through Himachal and Uttarakhand; the Lepcha tribe is native to the Darjeeling-Sikkim Himalayan region; and Namcha Barwa peak marks the eastern end of the Arunachal Himalayas.", "subject": "Geography", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "What are not true about the Peninsular Plateau? (i) Height of this plateau is approximately 1000-1500 metres (ii) Height generally decreases from West to East (iii) On its East there are Gir Ranges and on West there are Rajmahal Hills", "options": {"A": "(i) and (ii)", "B": "(ii) and (iii)", "C": "(i) and (iii)", "D": "None of the above"}, "correct": "C", "explanation": "The Peninsular Plateau's average elevation is generally lower (around 600-900m in most parts), and the hill ranges are reversed in the statement — the Gir Hills actually lie in the west (Gujarat) and the Rajmahal Hills in the east (Jharkhand), not vice versa.", "subject": "Geography", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "What are true in relation to jet stream? (i) Jet stream blows across Asian Continent at latitudes North of Himalayas parallel to Tibetan highlands (ii) Tibetan highland divides jet stream into North and South branches (iii) The northern branch of jet stream plays an important role in winter weather in India", "options": {"A": "(i) and (ii)", "B": "(i) and (iii)", "C": "(i), (ii) and (iii)", "D": "None of the above"}, "correct": "C", "explanation": "All three statements about the sub-tropical westerly jet stream and its role (including bringing western disturbances that affect North Indian winter weather) are correct.", "subject": "Geography", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Arrange the following biosphere reserves in decreasing order of their geographical area:", "options": {"A": "Panchmarhi > Khangchendzonga > Panna > Nanda Devi > Agasthyamalai", "B": "Nanda Devi > Panchmarhi > Panna > Agasthyamalai > Khangchendzonga", "C": "Panchmarhi > Nanda Devi > Agasthyamalai > Panna > Khangchendzonga", "D": "Nanda Devi > Panchmarhi > Agasthyamalai > Panna > Khangchendzonga"}, "correct": "D", "explanation": "By area, Nanda Devi Biosphere Reserve is the largest among these, followed by Panchmarhi, Agasthyamalai, Panna, and Khangchendzonga.", "subject": "Geography", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Arrange the following soils of India as per USDA classification by ICAR in decreasing order of area coverage:", "options": {"A": "Ultisols > Entisols > Alfisols > Aridisols", "B": "Entisols > Alfisols > Ultisols > Aridisols", "C": "Entisols > Alfisols > Aridisols > Ultisols", "D": "Alfisols > Aridisols > Ultisols > Entisols"}, "correct": "C", "explanation": "Entisols cover the largest area among India's soil orders, followed by Alfisols, then Aridisols, with Ultisols covering the smallest area among these four.", "subject": "Geography", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Read the following statements and choose the correct option: (i) Moving away from the sea, force of tropical cyclone decreases (ii) Tropical cyclone gets its energy from release of latent heat on condensation of moisture gathered over the ocean, which decreases moving away from sea", "options": {"A": "(i) and (ii) both true, (ii) correctly explains (i)", "B": "(i) and (ii) both true, but (ii) is not correct reasoning", "C": "(i) is true, (ii) is false", "D": "(i) and (ii) both false"}, "correct": "A", "explanation": "A tropical cyclone weakens as it moves inland because it loses its primary energy source — latent heat released from moisture drawn over the warm ocean surface — correctly explaining statement (i).", "subject": "Geography", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Match the Crops shown in Column-I to States in Column-II where they are grown maximum: (a) Ragi (b) Bazra (c) Jowar (d) Urad -- (i) Karnataka (ii) Maharashtra (iii) Rajasthan (iv) Madhya Pradesh", "options": {"A": "(i)(ii)(iii)(iv)", "B": "(i)(iii)(ii)(iv)", "C": "(iii)(iv)(ii)(i)", "D": "(i)(iv)(iii)(ii)"}, "correct": "B", "explanation": "Karnataka is the top producer of Ragi, Rajasthan of Bajra, Maharashtra of Jowar, and Madhya Pradesh of Urad.", "subject": "Geography", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Which of the following statements is not true?", "options": {"A": "On the basis of wind power installed capacity, India ranks fourth in the world", "B": "The total wind power installed capacity of India is about 400 GW", "C": "Among Indian States, maximum wind power potential (at 100m above ground level) is in Gujarat", "D": "None of the above"}, "correct": "B", "explanation": "India's actual total installed wind power capacity around this period was roughly 40 GW, not 400 GW; India does rank fourth globally in wind capacity, and Gujarat has the highest wind power potential among Indian states.", "subject": "Environment/Economy", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "What is/are true in reference to QUAD group? (i) First Summit of leaders of QUAD group was held in 2017 (ii) QUAD 2022 Summit was held on 24th April in Tokyo (iii) Initiative on Indo-Pacific Partnership for Maritime Domain Awareness (IPMDA) was announced in QUAD 2022 Summit", "options": {"A": "(i) and (iii)", "B": "(i) and (ii)", "C": "Only (iii)", "D": "(i), (ii) and (iii)"}, "correct": "C", "explanation": "The first-ever Quad Leaders' Summit was actually held in 2021, not 2017 (2017 saw only official-level talks); the 2022 Quad Summit in Tokyo was held on 24 May, not April; the IPMDA initiative was indeed announced at that 2022 Tokyo Summit.", "subject": "Current Affairs", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "What are true in relation to the 44th Chess Olympiad, 2022 held in Chennai? (i) 188 teams in open category and 162 teams in women category participated (ii) Total 6 teams from India participated (iii) India won Bronze Medal in open and women category", "options": {"A": "(i), (ii) and (iii)", "B": "(i) and (ii)", "C": "(i) and (iii)", "D": "None of the above"}, "correct": "A", "explanation": "As host nation, India fielded 6 teams (3 each in open and women categories) among 188 open and 162 women teams overall, and Indian teams won bronze medals in both the open and women's sections.", "subject": "Sports/Current Affairs", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Where was the final match of FIFA U-17 Women's World Cup, 2022 held?", "options": {"A": "Kalinga Stadium, Bhubaneswar", "B": "Pt. Jawaharlal Nehru Stadium, Margao", "C": "D. Y. Patil Stadium, Navi Mumbai", "D": "None of the above"}, "correct": "C", "explanation": "The final of the FIFA U-17 Women's World Cup 2022 was played at the D.Y. Patil Stadium, Navi Mumbai.", "subject": "Sports/Current Affairs", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "What is/are true in relation to the Padma Vibhushan Award given in 2022? (i) Total four people were given the award (ii) In total two people were given the award posthumously (iii) Prabha Atre was also given this award", "options": {"A": "(i), (ii) and (iii)", "B": "(i) and (iii)", "C": "Only (i)", "D": "Only (iii)"}, "correct": "A", "explanation": "The 2022 Padma Vibhushan was conferred on four people — Zakir Hussain, Prabha Atre, and (posthumously) Gen. Bipin Rawat and Radheshyam Khemka.", "subject": "Current Affairs", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Who was given the President's Police Medal for Distinguished Service in 2022?", "options": {"A": "Gurminder Singh", "B": "Milap Chand", "C": "Mohsen Shahedi", "D": "Atul Karwal"}, "correct": "D", "explanation": "Shri Atul Karwal, a senior Chhattisgarh-cadre IPS officer, was among those conferred the President's Police Medal for Distinguished Service in 2022.", "subject": "Current Affairs", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "What is the name of the last PSLV mission of ISRO which was launched in 2022?", "options": {"A": "PSLV-C54", "B": "PSLV-C53", "C": "PSLV-C52", "D": "PSLV-C51"}, "correct": "A", "explanation": "PSLV-C54, which launched the Oceansat-3 (EOS-06) mission in November 2022, was ISRO's last PSLV mission of that year.", "subject": "Current Affairs", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "India is hosting which Annual Summit of G20?", "options": {"A": "17th", "B": "18th", "C": "19th", "D": "16th"}, "correct": "B", "explanation": "India hosted the 18th G20 Summit (held in New Delhi in 2023).", "subject": "Current Affairs", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Who was awarded the International Booker Prize, 2022?", "options": {"A": "Farah Bashir", "B": "Namita Gokhale", "C": "Chitra Divakaruni", "D": "Geetanjali Shree"}, "correct": "D", "explanation": "Geetanjali Shree won the International Booker Prize 2022 for 'Tomb of Sand' (Ret Samadhi), the first Hindi novel to win the award.", "subject": "Current Affairs", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "What is not true about Late Queen Elizabeth II?", "options": {"A": "She officially visited India twice", "B": "She was Chief Guest at India's Republic Day in 1961", "C": "She visited India to participate in the 50th Anniversary of India's Independence", "D": "None of the above"}, "correct": "A", "explanation": "Queen Elizabeth II actually visited India three times (1961, 1983 and 1997), not twice.", "subject": "Current Affairs", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "Choose the incorrect match:", "options": {"A": "HRIDAY–Heritage City Development and Augmentation Yojana", "B": "SEHAT–Social Endeavour for Healthcare and Telemedicine", "C": "AMRUT–Atal Mission for Rejuvenation and Urban Transformation", "D": "None of the above"}, "correct": "B", "explanation": "SEHAT actually stands for 'Social Endeavour for Health and Telemedicine' (not 'Healthcare and Telemedicine'), making this the incorrect match.", "subject": "Governance", "exam": "CGPSC Prelims Paper-I 2022"}, {"q": "What is/are not true in reference to G20? (i) G20 is official group of European Union and other 19 countries (ii) G20 has its Headquarter in London (iii) In reference to groups made for electing President, India is part of Group-2 which has other members as Russia, South Africa and Turkey", "options": {"A": "(i), (ii) and (iii)", "B": "(i) and (ii)", "C": "(i) and (iii)", "D": "Only (ii)"}, "correct": "D", "explanation": "G20 has no fixed permanent headquarters — the presidency and secretariat functions rotate annually among member countries, so claiming it is headquartered in London is not true.", "subject": "Current Affairs", "exam": "CGPSC Prelims Paper-I 2022"}]};